import {test,beforeAll,afterAll,afterEach,inject} from 'vitest';
import assert from 'node:assert/strict';
import * as Y from 'yjs';
import {makeDriver} from 'board-test-driver';
import {Adapter} from '../../packages/board-sync/src/document-adapter.ts';
import {readBoard} from '../../packages/board-sync/src/codec.ts';
import {add,canonical} from '../../packages/board-rules/src/document.ts';
import {encode,decode} from '../../packages/board-sync/src/session.ts';
import type {Context,Driver,Peer} from './driver-types.ts';
declare module 'vitest' { export interface ProvidedContext { board:Context; runner:string; } }
const context=inject('board'),runner=inject('runner');
let driver:Driver,f:any,at=Date.now(),pass=0,fail=0;
const peers:Peer[]=[],docs:Y.Doc[]=[],measure:Record<string,unknown>={},scenarios=new Map<number,()=>Promise<void>>();
const sources=['board_role','access_changes_after','lifecycle_value','carry_board_mentions','copy_saved_board'];
beforeAll(async()=>{driver=await makeDriver(context);});
async function resetControls(){
  for(const rpc of sources)await helper('proxy',{rpc,release:rpc,fail:false,failAfter:false,hold:false,holdBefore:false});
  // Node's fence-permission control returns without forwarding other fields to IPC.
  await driver.control({fenceUnreadable:false});
  await driver.control({releaseRoom:true,holdRoom:'',failVoting:'',failTimer:'',failHistory:'',failCheckpoint:'',fixedNow:null});
}
afterEach(async()=>{await resetControls();for(const p of peers.splice(0))await p.close();for(const d of docs.splice(0))d.destroy();});
afterAll(async()=>{await driver.close();console.log('SUMMARY-SPOTLIGHT '+JSON.stringify({runner,checks:pass+fail,pass,fail,measure}));});
async function helper(action:string,value:unknown={}):Promise<any>{const r=await fetch(context.helperUrl+'/'+action,{method:'POST',body:JSON.stringify(value)}),v=await r.json();assert(r.ok,JSON.stringify(v));return v;}
const rpc=(name:string,parameters:unknown)=>helper('rpc',{name,parameters});
async function req(path:string,who='owner',method='GET',body?:unknown){return driver.request(path,{method,headers:{Authorization:'Bearer '+f.people[who].token,Origin:context.origin,'Content-Type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});}
async function ok(path:string,who='owner',method='GET',body?:unknown,status=200):Promise<any>{const r=await req(path,who,method,body);assert.equal(r.status,status,await r.clone().text());return r.json();}
async function until<T>(read:()=>T|Promise<T>,accepts:(v:T)=>boolean=v=>!!v):Promise<NonNullable<T>>{const end=Date.now()+10000;for(;;){const v=await read();if(accepts(v))return v as NonNullable<T>;if(Date.now()>=end)throw Error('Spotlight condition timeout');await new Promise(r=>setTimeout(r,10));}}
async function clock(value:number){at=value;await driver.control({fixedNow:at});}
async function advance(ms=1001){await clock(at+ms);}
async function tokens(){for(const p of Object.values(f.people) as any[])p.token=await helper('token',{person:p,options:{now:at,exp:Math.floor(at/1000)+86400}});}
async function join(who='owner',board=f.a){const ticket=await ok(`/boards/${board}/join-tickets`,who,'POST',undefined,201),p=await driver.connect(`/boards/${board}/join?ticket=${ticket.ticket}`);peers.push(p);const j=await p.next('joined'),doc=new Y.Doc();docs.push(doc);Y.applyUpdate(doc,decode(j.update));assert(Object.hasOwn(j,'spotlight'),'joined spotlight capability');return {p,j,doc,who};}
type Client=Awaited<ReturnType<typeof join>>;
const projection=(c:Client)=>[...c.p.messages].reverse().find(v=>v.spotlight)?.spotlight;
async function info(extra:any={}){return driver.control({board:f.a,spotlight:extra});}
async function message(c:Client,action:string,extra:any={},pace=true){if(pace)await advance();const s=(await info()).session,own=projection(c)?.own;return {kind:'spotlight_command',requestId:crypto.randomUUID(),epoch:c.j.epoch,restoreGeneration:c.j.restoreGeneration,authorityId:s.authorityId,sessionId:s.sessionId,action,...(['follow','leave'].includes(action)?{expectedMembershipVersion:own?.membershipVersion??0}:{expectedControlVersion:s.controlVersion}),...extra};}
async function answer(c:Client,m:any,raw?:string){c.p.send(raw??m);return until(()=>c.p.messages.find(v=>v.requestId===m.requestId&&['spotlight_result','spotlight_refused','spotlight_snapshot'].includes(v.kind)));}
async function command(c:Client,action:string,extra:any={},pace=true){return answer(c,await message(c,action,extra,pace));}
async function accepted(c:Client,action:string,extra:any={},pace=true){const v=await command(c,action,extra,pace);assert.equal(v.kind,'spotlight_result',JSON.stringify(v));return v;}
async function read(c:Client,pace=true){if(pace)await advance();return answer(c,{kind:'spotlight_read',requestId:crypto.randomUUID(),epoch:c.j.epoch,restoreGeneration:c.j.restoreGeneration});}
async function presence(c:Client){c.p.send({kind:'presence',page:f.a,cursor:{x:42,y:22},selection:[],view:{x:10,y:20,width:800,height:600},active:false});await driver.control({board:f.a,settled:true});}
async function started(){const a=await join(),b=await join('editor'),r=await accepted(a,'start');await presence(a);await until(async()=>{await read(b);return b.p.messages.some(m=>m.kind==='present'&&m.connection===a.j.self.connection&&m.view.width===800);});return {a,b,r};}
async function closedAs(c:Client,code:number){await until(()=>c.p.closed!==null);assert.equal(c.p.closed,code);}
async function gone(c:Client,code:number){await closedAs(c,code);return until(()=>info({inspect:true}),data=>!data.attachments.some((v:any)=>v.connectionId===c.j.self.connection));}
async function closeWith(c:Client,code=4410,reason='retry_recovery'){
  await info({watchCloses:true});(c.p as any).closeWith(code,reason);await closedAs(c,code);
  // Client close and the server's close callback travel on different event loops.
  // This ordered probe waits for the actual callback and its queued cleanup.
  await until(async()=>{const data=await info({inspect:true});return data.closes?.some((v:any)=>v.connection===c.j.self.connection&&v.code===code&&v.reason===reason)&&!data.attachments.some((v:any)=>v.connectionId===c.j.self.connection);});
}
async function write(c:Client,board:any){const adapter=new Adapter();adapter.doc=c.doc;const vector=Y.encodeStateVector(c.doc);adapter.set(board);const m={kind:'edit',requestId:crypto.randomUUID(),epoch:c.j.epoch,restoreGeneration:c.j.restoreGeneration,update:encode(Y.encodeStateAsUpdate(c.doc,vector))};c.p.send(m);const result=await until(()=>c.p.messages.find(v=>v.requestId===m.requestId&&['saved','refused'].includes(v.kind)));assert.equal(result.kind,'saved',JSON.stringify(result));return result;}
async function seed(c:Client,count=4){let b=readBoard(c.doc);for(let i=0;i<count;i++)b=add(b,'sticky',i*260,0);await write(c,b);return b;}
async function seeded(count=4){const c=await join();await seed(c,count);return c;}
async function operator(action:string,body?:unknown){return driver.request(`/operator/boards/${f.a}/${action}`,{method:'POST',headers:{'Board-Operator-Key':context.operatorKey,'Content-Type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});}
async function backup(){const r=await operator('backup');assert.equal(r.status,200,await r.clone().text());return r.json() as Promise<any>;}
async function fresh(){await resetControls();for(const p of peers.splice(0))await p.close();for(const d of docs.splice(0))d.destroy();f=await helper('removal-fixture');await clock(Date.now());await tokens();}
async function vote(c:Client,action='start',extra:any={}){await advance();const row=(await driver.rows(f.a,'workshop_vote'))[0],m={kind:'vote_command',requestId:crypto.randomUUID(),epoch:c.j.epoch,restoreGeneration:c.j.restoreGeneration,sessionId:row.session_id,expectedSessionVersion:row.session_version,action,...(action==='start'?{page:f.a,prompt:'Choose',budget:3}:{}),...extra};c.p.send(m);return until(()=>c.p.messages.find(v=>v.requestId===m.requestId&&v.kind.startsWith('vote_')));}
async function historyIntent(){const list=await ok(`/boards/${f.a}/versions`),v=list.versions[0],input={requestId:crypto.randomUUID(),expectedRevision:list.head.revision,expectedGeneration:list.head.generation};await driver.control({failHistory:'fence'});assert.equal((await req(`/boards/${f.a}/versions/${v.id}/restore`,'owner','POST',input)).status,503);return {v,input};}
const metadata=(data:any)=>data.attachments.map((a:any)=>({connection:a.connectionId,presenter:a.spotlightPresenter,member:a.spotlightMember}));
async function accountState(who:string,action:'disable'|'enable'){
  const response=await driver.request(`/operator/people/${f.people[who].id}/${action}`,{method:'POST',headers:{'Board-Operator-Key':context.operatorKey}});
  assert.equal(response.status,200);const result=await response.json() as any;assert.equal(result.removal,'done');return result;
}
async function forceEnd(cause:string,a:Client,b:Client){
  if(cause==='stop')await accepted(a,'stop');
  if(cause==='voting')assert.equal((await vote(a)).kind,'vote_result');
  if(cause==='revocation')await accountState(a.who,'disable');
  if(cause==='grace_expiry'){await advance(5000);await driver.control({board:f.a,alarm:true});}
  if(cause==='lifecycle')await ok(`/boards/${f.a}/trash`,'owner','POST',{requestId:crypto.randomUUID(),expectedCycle:0});
  if(cause==='recovery')await driver.control({board:f.a,raiseFence:true});
  if(cause==='last_leave'){await closeWith(a,1000,'');await closeWith(b,1000,'');}
}
const check=(id:number,name:string,fn:()=>Promise<void>)=>{scenarios.set(id,fn);return test(`S${id} ${name}`,async()=>{try{await import('../../packages/board-sync/src/spotlight.ts');f=await helper('removal-fixture');await clock(Date.now());await tokens();await fn();pass++;console.log(`PASS: S${id} ${name}`);}catch(error){fail++;console.log(`FAIL: S${id} ${name}`);throw error;}},id===352?300000:undefined);};
check(305,'all effective roles and granted guests present/follow; ungranted/disabled denied',async()=>{for(const who of ['owner','editor','viewer','granted']){const a=await join(who),b=await join(who==='owner'?'editor':'owner'),r=await accepted(a,'start');assert.equal(r.spotlight.session.presenter.connection,a.j.self.connection);assert.deepEqual(r.spotlight.session.presenter,{connection:a.j.self.connection,person:a.j.self.person,label:a.j.self.label,colour:a.j.self.colour});await presence(a);await accepted(b,'follow');await accepted(b,'leave');await accepted(b,'take_over');await accepted(b,'stop');}await ok(`/boards/${f.a}/grants/${f.people.granted.id}`,'owner','PUT',{role:'viewer'});const viewer=await join('granted');assert.equal(viewer.j.role,'viewer');await accepted(viewer,'start');await accepted(viewer,'stop');for(const who of ['plain','outsider'])assert.equal((await req(`/boards/${f.a}/join-tickets`,who,'POST')).status,404);await rpc('disable_person',{person:f.people.editor.id});assert.equal((await req(`/boards/${f.a}/join-tickets`,'editor','POST')).status,404);});
async function startRace(reverse=false){const a=await join(),b=await join('editor'),x=await message(a,'start'),y=await message(b,'start',{},false);const first=reverse?b:a,second=reverse?a:b;const [r,s]=await Promise.all([answer(first,reverse?y:x),answer(second,reverse?x:y)]);assert.equal(r.kind,'spotlight_result');assert.equal(s.reason,'spotlight_stale_session');await accepted(first,'stop');}
check(306,'simultaneous starts choose first receipt in either order',async()=>{await startRace();await startRace(true);});
check(307,'takeover races replace one session and invalidate old commands',async()=>{const {a,b,r}=await started(),c=await join('viewer'),x=await message(b,'take_over'),y=await message(c,'take_over',{},false);const [one,two]=await Promise.all([answer(b,x),answer(c,y)]);assert.equal(one.kind,'spotlight_result');assert.equal(two.reason,'spotlight_stale_session');assert.notEqual(one.spotlight.session.sessionId,r.spotlight.session.sessionId);assert.equal((await command(a,'stop',{sessionId:r.spotlight.session.sessionId,expectedControlVersion:1})).reason,'spotlight_stale_session');});
check(308,'only presenter connection can Stop including same-person other tab',async()=>{const {a}=await started(),tab=await join();assert.equal((await command(tab,'stop')).reason,'spotlight_not_presenter');await accepted(tab,'take_over');assert.equal((await command(a,'stop')).reason,'spotlight_not_presenter');assert.equal((await accepted(tab,'stop')).spotlight.session.phase,'idle');});
check(309,'control phase boundaries reserve suspension/terminal and never wrap',async()=>{
  const M=Number.MAX_SAFE_INTEGER;
  for(const action of ['start','take_over','resume'])for(const current of [M-3,M-2,M-1]){
    await fresh();const a=await join('editor'),b=await join('viewer');let r:any,next=a;
    if(action!=='start'){r=await accepted(a,'start');await presence(a);if(action==='resume'){await closeWith(a);next=await join('editor');await presence(next);}else next=b;}
    if(action==='take_over'&&current===M-1){await info({controlVersion:M-2});await info({connection:a.j.self.connection,suspend:true});}else await info({controlVersion:current});
    const before=await info(),result=await command(next,action,action==='resume'?{resumeKey:r.resumeKey}:{},false),after=await info();
    if(current===M-3){assert.equal(result.kind,'spotlight_result');assert.equal(after.session.controlVersion,M-2);if(action==='take_over')assert.notEqual(after.session.sessionId,before.session.sessionId);}
    else{assert.equal(result.reason,'spotlight_version_exhausted');assert.deepEqual(after.session,before.session);assert(JSON.stringify(metadata(after))===JSON.stringify(metadata(before)),'Spotlight metadata changed');}
  }
  for(const cause of ['stop','voting','revocation','grace_expiry','lifecycle','recovery','last_leave']){
    await fresh();const a=await join('editor'),b=await join('viewer');await seed(a);await accepted(a,'start');await presence(a);await accepted(b,'follow');await info({controlVersion:M-2});await info({connection:a.j.self.connection,suspend:true});assert.equal((await info()).session.controlVersion,M-1);await forceEnd(cause,a,b);const end=await info({inspect:true});assert.equal(end.session.phase,'idle',cause);assert.equal(end.session.controlVersion,M,cause);assert.equal(end.session.graceDeadline,null,cause);assert(end.attachments.every((a:any)=>!a.spotlightPresenter&&!a.spotlightMember?.following),cause);
    if(cause==='lifecycle'||cause==='recovery'||cause==='last_leave'){
      const closed=await gone(b,cause==='lifecycle'?4403:cause==='recovery'?4423:1000);assert.equal(closed.session.controlVersion,M,cause);assert.equal(closed.session.graceDeadline,null,cause);
    }else{
      assert(end.attachments.some((v:any)=>v.connectionId===b.j.self.connection),`Expected live follower after ${cause}`);
      if(cause==='voting'){
        assert.equal((await command(b,'start')).reason,'spotlight_voting');
        assert.equal((await vote(a,'reveal')).kind,'vote_result');
        assert.equal((await vote(a,'clear')).kind,'vote_result');
      }
      assert.equal((await command(b,'start')).reason,'spotlight_version_exhausted');assert.equal((await info()).session.controlVersion,M);
    }
  }
  await fresh();const {a,b}=await started(),stop=await message(a,'stop');await answer(a,stop);assert.equal((await answer(a,{...stop,requestId:crypto.randomUUID()})).reason,'spotlight_stale_session');assert.equal((await command(b,'start',{authorityId:crypto.randomUUID()})).reason,'spotlight_stale_session');
});
check(310,'independent members succeed and delayed leave is stale',async()=>{const {b}=await started(),c=await join('viewer');await Promise.all([accepted(b,'follow'),accepted(c,'follow')]);const old=await message(b,'leave');await accepted(b,'leave');await accepted(b,'follow');assert.equal((await answer(b,old)).reason,'spotlight_stale_member');assert.equal((await read(b)).spotlight.own.following,true);});
check(311,'two tabs count one distinct follower person',async()=>{const {a,b}=await started(),tab=await join('editor'),c=await join('viewer');for(const p of [b,tab,c])await accepted(p,'follow');assert.equal((await read(a)).spotlight.presenting.followers,2);await accepted(b,'leave');assert.equal((await read(a)).spotlight.presenting.followers,2);await accepted(tab,'leave');assert.equal((await read(a)).spotlight.presenting.followers,1);});
check(312,'presenter count retains had-follower and peers receive no count',async()=>{const {a,b}=await started();assert.deepEqual((await read(a)).spotlight.presenting,{followers:0,hasHadFollower:false});await accepted(b,'follow');assert.equal((await read(b)).spotlight.presenting,null);await accepted(b,'leave');assert.deepEqual((await read(a)).spotlight.presenting,{followers:0,hasHadFollower:true});});
check(313,'held authority serializes later command and read',async()=>{const {a,b}=await started();await helper('proxy',{rpc:'board_role',holdBefore:true,clearLog:true,parameters:{board:f.a,person:f.people.editor.id}});const one=message(b,'take_over').then(m=>answer(b,m));await until(async()=>(await helper('proxy')).some((r:any)=>r.name==='board_role'&&r.heldAt));const two=read(a);await helper('proxy',{release:'board_role'});assert.equal((await one).kind,'spotlight_result');assert.equal((await two).spotlight.session.presenter.connection,b.j.self.connection);});
check(314,'forged fields and action-specific shape use dedicated refusals',async()=>{const c=await join();for(const field of ['actor','role','person','colour','presenter','followers','resumeKey'])assert.equal((await command(c,'start',{[field]:1})).reason,'spotlight_bad_message');assert(!c.p.messages.some(m=>m.kind==='refused'));});
check(315,'recipient frames whitelist key exclusively in presenter result',async()=>{const {a,b,r}=await started();assert.match(r.resumeKey,/^[0-9a-f]{64}$/);const joined=await join('viewer');for(const c of [b,joined])assert(!JSON.stringify(c.p.messages).includes('resumeKey'));await accepted(b,'follow');assert.deepEqual(Object.keys((await read(b)).spotlight).sort(),['own','presenting','session']);assert.equal((await read(b)).spotlight.presenting,null);assert(!JSON.stringify(await info()).includes('roster'));assert.equal(a.j.spotlight.session.phase,'idle');});
check(316,'1024 inclusive and 1025 whitespace request bound',async()=>{const c=await join(),m=await message(c,'start'),s=JSON.stringify(m);assert.equal((await answer(c,m,s+' '.repeat(1025-new TextEncoder().encode(s).length))).reason,'spotlight_message_too_large');const n=await message(c,'start'),t=JSON.stringify(n);assert.equal((await answer(c,n,t+' '.repeat(1024-new TextEncoder().encode(t).length))).kind,'spotlight_result');for(const v of c.p.messages.filter(m=>m.kind.startsWith('spotlight_')))assert(new TextEncoder().encode(JSON.stringify(v)).length<=4096);});
check(317,'separate five-attempt budgets and exact rolling boundary',async()=>{const c=await join();for(let i=0;i<5;i++)assert.equal((await command(c,'start',{forged:1},false)).reason,'spotlight_bad_message');assert.equal((await command(c,'start',{},false)).reason,'spotlight_rate_limited');assert.equal((await read(c,false)).kind,'spotlight_snapshot');await advance(1000);await accepted(c,'start',{},false);});
check(318,'metadata and full serialized attachment bounds on runner',async()=>{const {a,b}=await started();await accepted(b,'follow');await driver.control({board:f.a,reactions:{connection:a.j.self.connection,patch:{reactionTimes:Array(5).fill(Number.MAX_SAFE_INTEGER)}}});const data=await info();const bytes=(v:any)=>new TextEncoder().encode(JSON.stringify(v)).length;for(const v of data.attachments){assert(bytes(v)<=16384);assert(bytes({presenter:v.spotlightPresenter,member:v.spotlightMember})<=1024);for(const budget of [v.spotlightTimes??[],v.spotlightReadTimes??[]]){assert(budget.length<=5);assert(bytes(budget)<=1024);}}measure.attachmentMax=Math.max(...data.attachments.map(bytes));assert((await read(a)).spotlight.presenting.followers===1);});
check(319,'placeholder rejected, fresh active=false ordinary presence accepted',async()=>{const a=await join(),b=await join('viewer');await accepted(a,'start');assert.equal((await command(b,'follow')).reason,'spotlight_state');await presence(a);await accepted(b,'follow');assert.equal((await command(a,'follow')).reason,'spotlight_state');});
check(320,'presenter spatial relay is withheld on required-source outage',async()=>{const {a,b}=await started(),before=b.p.messages.length;await helper('proxy',{rpc:'board_role',fail:true,parameters:{board:f.a,person:f.people.owner.id}});await presence(a);assert(!b.p.messages.slice(before).some(m=>m.kind==='present'&&m.connection===a.j.self.connection));await helper('proxy',{rpc:'board_role',fail:false});await presence(a);await until(()=>b.p.messages.slice(before).some(m=>m.kind==='present'));});
for(const [id,code] of [[321,1000],[322,1001]] as const)check(id,`original clean ${code} ends without grace`,async()=>{const {a,b}=await started();await accepted(b,'follow');await closeWith(a,code,'');assert.equal((await read(b)).spotlight.session.phase,'idle');assert(b.p.messages.some(m=>m.kind==='spotlight_state'&&m.cause==='left'));});
check(323,'reloaded account without page key cannot resume',async()=>{const {a,b}=await started();await closeWith(a);const next=await join();await presence(next);assert.equal((await command(next,'resume',{resumeKey:'0'.repeat(64)},false)).reason,'spotlight_state');await advance(5000);assert.equal((await read(b)).spotlight.session.phase,'idle');});
check(324,'actual recoverable wire close reserves exactly 5000ms',async()=>{const {a,b}=await started();await closeWith(a);const p=(await read(b,false)).spotlight.session;assert.equal(p.phase,'reconnecting');assert.equal(p.graceDeadline,at+5000);await advance(4999);assert.equal((await read(b,false)).spotlight.session.graceDeadline,p.graceDeadline);});
check(325,'4999ms fresh same-page rebind rotates capability',async()=>{const {a,b,r}=await started();await accepted(b,'follow');await closeWith(a);const next=await join();await presence(next);await advance(4999);const x=await accepted(next,'resume',{resumeKey:r.resumeKey},false);assert.equal(x.spotlight.session.sessionId,r.spotlight.session.sessionId);assert.notEqual(x.resumeKey,r.resumeKey);assert.equal((await read(b,false)).spotlight.own.following,true);});
check(326,'5000ms expiry cannot be renewed by reads or guessing',async()=>{
  for(const explicitAlarm of [false,true]){
    await fresh();const {a,b,r}=await started();await closeWith(a);const next=await join();await presence(next);
    const grace=(await info()).session;assert.equal(grace.phase,'reconnecting');assert.equal(grace.graceDeadline,at+5000);
    assert.equal((await command(next,'resume',{resumeKey:'0'.repeat(64)},false)).reason,'spotlight_state');
    for(const peer of [b,next])assert.equal((await read(peer,false)).spotlight.session.graceDeadline,grace.graceDeadline);
    // Keep the admitted suspended identity: rebuilding after an alarm would target
    // current idle state and correctly receive spotlight_state instead of stale.
    const resume=await message(next,'resume',{resumeKey:r.resumeKey},false);
    await clock(grace.graceDeadline+(explicitAlarm?1:0));
    if(explicitAlarm)await driver.control({board:f.a,alarm:true});
    const response=await answer(next,resume);assert.equal(response.reason,'spotlight_stale_session');const idle=(await read(b,false)).spotlight.session;assert.equal(idle.phase,'idle');assert.equal(idle.graceDeadline,null);assert.equal(idle.controlVersion,grace.controlVersion+1);
  }
});
