check(353,'actual retrying BoardSession paths preserve waiting work and send 4410 with fixed reason',async()=>{
  const {BoardSession}=await import('../../packages/board-sync/src/session.ts');
  for(const path of ['interrupt','offline','reconnect','deadline','send_failure','discard','unavailable','close']){
    await fresh();const {a,b,r}=await started();await accepted(b,'follow');await info({watchCloses:true});let progress=0,failSend=false;const tasks=new Set<any>(),wireCloses:any[]=[],opened:Client[]=[],events:any[]=[];
    const session=await BoardSession.join({ticket:async()=>'',clock:{now:()=>progress,after:(ms:number,run:()=>void)=>{const task={at:progress+ms,run};tasks.add(task);return()=>tasks.delete(task);}},open:async()=>{const c=opened.length?await join():a;opened.push(c);return {send:(text:string)=>{if(failSend)throw Error('Synthetic send failure');c.p.send(text);},close:(code:number,reason?:string)=>{wireCloses.push({code,reason});(c.p as any).closeWith(code,reason);},listen:(h:any)=>c.p.listen(h)};}});session.subscribe(e=>events.push(e));
    let waiting:string|undefined,update:string|undefined;
    if(path==='deadline'||path==='send_failure'){if(path==='deadline')await driver.control({holdRoom:'message'});else failSend=true;waiting=session.edit({...session.board,title:'Unconfirmed synthetic work'});update=session.requests.get(waiting!)?.update;if(path==='deadline'){progress=10000;for(const task of [...tasks])if(task.at<=progress){tasks.delete(task);task.run();}}assert.equal(session.requests.get(waiting!)?.state,'waiting');assert.equal(events.at(-1).code,path==='deadline'?4000:1006);if(path==='deadline')assert.equal(events.at(-1).reason,'answer_deadline');}
    else if(path==='offline')session.interrupt();else if(path==='discard')session.discard('chosen_reason');else await (session as any)[path]();
    const terminal=['discard','unavailable','close'].includes(path);assert.deepEqual(wireCloses[0],{code:terminal?1000:4410,reason:terminal?undefined:'retry_recovery'},path);
    // Hosted finish's later cleanup must use the same recoverable wire cause.
    if(path==='offline')(a.p as any).closeWith(4410,'retry_recovery');
    await driver.control({releaseRoom:true,holdRoom:''});await until(()=>a.p.closed!==null);const data=await info();assert(data.closes.some((v:any)=>v.code===(terminal?1000:4410)&&v.reason===(terminal?'':'retry_recovery')));assert.equal((await read(b,false)).spotlight.session.phase,terminal?'idle':'reconnecting',path);
    if(waiting){assert.equal(session.requests.get(waiting)?.state,'waiting');assert.equal(session.requests.get(waiting)?.update,update);}
    if(!terminal){const next=opened.length>1?opened.at(-1)!:await join();await presence(next);await accepted(next,'resume',{resumeKey:r.resumeKey},false);assert.equal((await read(b,false)).spotlight.own.following,true);await accepted(next,'stop');}session.close();
  }
});
