    await fresh();const {a,b}=await started();await info({watchCloses:true});await closeWith(a,code,code===4410?'retry_recovery':'');const data=await info();assert(data.closes.some((v:any)=>v.code===code&&v.reason===(code===4410?'retry_recovery':'')));assert.equal((await read(b,false)).spotlight.session.phase,code===4410?'reconnecting':'idle');
