  await closeWith(a);const next=await join();await presence(next);await accepted(next,'resume',{resumeKey:active.key},false);assert.equal((await read(b,false)).spotlight.own.membershipVersion,M-2);assert.equal((await read(b,false)).spotlight.own.following,true);
  const rotated=(await info()).attachments.find((v:any)=>v.connectionId===next.j.self.connection).spotlightPresenter;await closeWith(next);const third=await join();await presence(third);await accepted(third,'resume',{resumeKey:rotated.key},false);const exhausted=(await read(b,false)).spotlight;assert.deepEqual(exhausted.own,{membershipVersion:M-1,following:false});assert.equal((await read(c,false)).spotlight.own.following,true);assert(b.p.messages.some(m=>m.kind==='spotlight_refused'&&m.requestId===null&&m.reason==='spotlight_version_exhausted'));await accepted(third,'stop');const finalized=(await info()).attachments.find((v:any)=>v.connectionId===b.j.self.connection).spotlightMember;assert.deepEqual(finalized,{sessionId:rotated.session.sessionId,membershipVersion:M,following:false,finalized:true});assert.equal((await command(third,'stop')).reason,'spotlight_not_presenter');assert.deepEqual((await info()).attachments.find((v:any)=>v.connectionId===b.j.self.connection).spotlightMember,finalized);const newStart=await accepted(third,'start');assert.notEqual(newStart.spotlight.session.sessionId,rotated.session.sessionId);assert.deepEqual((await read(b)).spotlight.own,{membershipVersion:0,following:false});
